import json,pathlib,base64
L=lambda n:'data:image/png;base64,'+base64.b64encode(open(f'/tmp/sflv/l3/{n}.png','rb').read()).decode()
CH=L('chromeT')
ph=lambda n:'data:image/webp;base64,'+base64.b64encode(open(f'/home/user/SFL/public/actus/couvertures/{n}-1200.webp','rb').read()).decode()
CG,BC,SI,CO=ph('cage-1'),ph('banc-1'),ph('silhouette-1'),ph('course-2')
B='#FFFFFF'; G='#2F7D4E'
FONTS='<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@800&display=block">'
CSS='*{box-sizing:border-box;margin:0}.H{font-family:Anton,sans-serif;text-transform:uppercase;line-height:.84;white-space:nowrap;color:#fff;letter-spacing:-.005em}.C{padding-top:.16em;background:linear-gradient(180deg,#d9dde0 0%,#d9dde0 12%,#ffffff 18%,#eef0f2 44%,#9aa1a8 51%,#3a3f44 54%,#8d949b 62%,#f2f4f5 84%,#b9bec3 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-stroke:.3px rgba(255,255,255,.7);filter:drop-shadow(0 .6px 0 rgba(0,0,0,.9)) drop-shadow(0 2px 3px rgba(0,0,0,.8))}.O{color:transparent;-webkit-text-stroke:.35px rgba(255,255,255,.55)}.m{font:800 3.2px Inter;letter-spacing:.3em;text-transform:uppercase;color:rgba(255,255,255,.7)}'
halo='<div style="position:absolute;inset:0;backdrop-filter:blur(1.2px) brightness(1.15) contrast(1.05);-webkit-backdrop-filter:blur(1.2px) brightness(1.15);mix-blend-mode:screen;opacity:.35;pointer-events:none"></div>'
grain='<svg style="position:absolute;inset:0;width:100%;height:100%;mix-blend-mode:overlay;pointer-events:none"><filter id="gr"><feTurbulence type="fractalNoise" baseFrequency="1.5" numOctaves="3" seed="9"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="table" tableValues="0 .28"/></feComponentTransfer></filter><rect width="100%" height="100%" filter="url(#gr)"/></svg>'
def photo(src,pos='center',dark=.55): return f'<div style="position:absolute;inset:0;background:url({src}) {pos}/cover;filter:grayscale(1) contrast(1.28) brightness(.92) sepia(.08) hue-rotate(170deg) saturate(.6)"></div><div style="position:absolute;inset:0;background:rgba(0,0,0,{dark})"></div>'+vig
vig='<div style="position:absolute;inset:0;background:radial-gradient(120% 90% at 50% 45%,transparent 45%,rgba(0,0,0,.75))"></div>'
edge=lambda c='rgba(255,255,255,.18)',i=4:f'<div style="position:absolute;inset:{i}px;border:.5px solid {c}"></div>'
glow=lambda o=.22:f'<div style="position:absolute;left:50%;top:50%;width:70%;height:80%;transform:translate(-50%,-50%);background:radial-gradient(closest-side,rgba(255,255,255,{o}),transparent)"></div>'
def spot(x='50%',y='45%',r=.35): return f'<div style="position:absolute;inset:0;background:radial-gradient(60% 55% at {x} {y},rgba(255,255,255,{r*.5}),transparent 70%);mix-blend-mode:screen"></div>'
def hero(h,refl=True,streak=True):
    st=f'<div style="position:absolute;left:50%;top:50%;width:{h*9}px;height:{h*.06}px;transform:translate(-50%,-50%);background:linear-gradient(90deg,transparent,rgba(255,255,255,.85) 50%,transparent);filter:blur({h*.03}px)"></div><div style="position:absolute;left:50%;top:50%;width:{h*2.2}px;height:{h*.9}px;transform:translate(-50%,-50%);background:radial-gradient(closest-side,rgba(255,255,255,.22),transparent)"></div>' if streak else ''
    rf=f'<img src="{CH}" style="position:absolute;left:0;top:100%;height:{h}px;transform:scaleY(-1);opacity:.28;-webkit-mask-image:linear-gradient(to top,rgba(0,0,0,.9),transparent 55%);mask-image:linear-gradient(to top,rgba(0,0,0,.9),transparent 55%);margin-top:{h*.04}px">' if refl else ''
    contact=f'<div style="position:absolute;left:8%;right:8%;top:{h*.92}px;height:{h*.22}px;background:radial-gradient(closest-side,rgba(0,0,0,.85),transparent);filter:blur({h*.04}px)"></div>'
    return f'<div style="position:relative">{st}{contact}<img src="{CH}" style="position:relative;height:{h}px;display:block;filter:drop-shadow(0 {h*.06}px {h*.1}px rgba(0,0,0,.9))">{rf}</div>'
def bug(a,b,sa,sb,fs=4):
    return f'<div style="display:flex;align-items:stretch;font:800 {fs}px Inter;letter-spacing:.14em;text-transform:uppercase;box-shadow:0 1px 4px rgba(0,0,0,.6)"><span style="background:#0A0A0A;color:#fff;padding:{fs*.7}px {fs}px">{a}</span><span style="background:#fff;color:#0A0A0A;padding:{fs*.7}px {fs*.9}px;font-family:Anton;font-size:{fs*1.6}px;letter-spacing:0;line-height:1">{sa}–{sb}</span><span style="background:#0A0A0A;color:#fff;padding:{fs*.7}px {fs}px">{b}</span></div>'
logo=lambda h,extra='':f'<img src="{CH}" style="height:{h}px;display:block;filter:drop-shadow(0 {h*.08}px {h*.12}px rgba(0,0,0,.85)){extra}">'
def foot(w,h):
    fs=max(2.2,min(w,h)*.022)
    return f'<div style="position:absolute;left:{w*.04}px;right:{w*.04}px;bottom:{h*.03}px;display:flex;justify-content:space-between;font:800 {fs}px Inter;letter-spacing:.32em;text-transform:uppercase;color:rgba(255,255,255,.42)"><span>S1 · 2026</span><span>Métropole lilloise</span></div>'
JOBS=[]
def job(path,w,h,sc,inner):
    f=pathlib.Path('html')/(path.replace('/','__')+'.html'); f.parent.mkdir(exist_ok=True)
    f.write_text(f'<!DOCTYPE html><html><head><meta charset="utf-8">{FONTS}<style>{CSS}body{{width:{w}px;height:{h}px}}</style></head><body><div style="position:relative;overflow:hidden;width:{w}px;height:{h}px;background:#050505">{inner}{halo}{foot(w,h) if path.split('/')[0] in ('youtube','twitch','instagram') and 'panneau' not in path and 'filigrane' not in path and 'miniature' not in path else ''}{grain}</div></body></html>')
    JOBS.append({'html':str(f.resolve()),'out':path,'w':w,'h':h,'scale':sc})

cartes=lambda n:'data:image/webp;base64,'+base64.b64encode(open(f'/tmp/sflv/quatre/{n}.webp','rb').read()).decode()
W,Hh=180,225
def slide(n,bg,inner,num): job(f'manifeste/{n}',W,Hh,6,bg+f'<div style="position:absolute;left:12px;top:13px">{logo(11)}</div><div class="m" style="position:absolute;right:12px;top:15px">{num} / 06</div>'+inner+edge())
slide('01-une-nouvelle-ere',photo(SI,'center',.5)+spot('50%','35%',.4),f'<div class="H" style="position:absolute;left:12px;top:122px;font-size:13px">Le foot à 5 entre dans</div><div class="H C" style="position:absolute;left:12px;top:138px;font-size:30px">Une nouvelle</div><div class="H C" style="position:absolute;left:12px;top:164px;font-size:30px">ère.</div>','01')
slide('02-pas-d-equipe',photo(BC,'center 60%',.72),f'<div class="H C" style="position:absolute;left:12px;top:50px;font-size:46px">Pas</div><div class="H C" style="position:absolute;left:12px;top:88px;font-size:40px">d’équipe.</div><div class="m" style="position:absolute;left:12px;top:140px;font-size:4.2px;line-height:1.7;color:#ddd;letter-spacing:.24em">Pas de club. Pas de capitaine.<br>Pas de pote à convaincre.</div>','02')
slide('03-tu-viens-seul',photo(CG,'center 55%',.6)+spot('50%','55%',.3),f'<div class="H" style="position:absolute;left:0;right:0;top:80px;text-align:center;font-size:13px">Chaque dimanche,</div><div class="H C" style="position:absolute;left:0;right:0;top:96px;text-align:center;font-size:30px">Tu viens seul.</div><div class="m" style="position:absolute;left:0;right:0;top:132px;text-align:center;font-size:4px;color:#ddd">L’app fait les équipes. Noirs contre Blancs.</div>','03')
slide('04-mercenaires',photo(CO,'center 45%',.55),f'<div class="H" style="position:absolute;left:12px;top:46px;font-size:13px">Ici, on est tous des</div><div class="H C" style="position:absolute;left:12px;top:60px;font-size:29px">Mercenaires.</div><div class="m" style="position:absolute;left:12px;bottom:24px;font-size:4.2px;line-height:1.7;color:#ddd;letter-spacing:.24em">Coéquipier ce dimanche.<br>Adversaire le suivant.<br>Tu ne joues que pour toi.</div>','04')
slide('05-tout-compte',f'<div style="position:absolute;inset:0;background:#070707"></div>'+spot('70%','50%',.25)+f'<img src="{cartes("jouneiid-d1")}" style="position:absolute;right:12px;top:96px;width:50px;border-radius:3px;transform:rotate(5deg);box-shadow:0 6px 16px #000">',f'<div class="H C" style="position:absolute;left:12px;top:44px;font-size:34px">Tout</div><div class="H C" style="position:absolute;left:12px;top:72px;font-size:34px">compte.</div><div style="position:absolute;left:12px;top:124px;width:86px">{"".join(f"<div style=\'display:flex;justify-content:space-between;border-top:.5px solid rgba(255,255,255,.18);padding:3.5px 0\'><span class=\'m\' style=\'color:#fff\'>{a}</span><span class=\'H\' style=\'font-size:9px\'>{b}</span></div>" for a,b in [("Tes buts","✓"),("Tes passes","✓"),("Ta note","87"),("Ton rang","1er")])}</div>','05')
slide('06-viens-seul',photo(CG,'center 60%',.62)+spot('50%','34%'),f'<div style="position:absolute;left:50%;top:32%;transform:translate(-50%,-50%)">{hero(40)}</div><div class="H" style="position:absolute;left:0;right:0;top:128px;text-align:center;font-size:10px">13 dimanches. Une seule Pépite d’or.</div><div class="H C" style="position:absolute;left:0;right:0;top:146px;text-align:center;font-size:34px">Viens seul.</div><div style="position:absolute;left:50%;bottom:22px;transform:translateX(-50%);background:#F4F4F2;color:#0A0A0A;font:800 4.4px Inter;letter-spacing:.28em;padding:5px 9px;white-space:nowrap">GETBOLA.APP/SFL</div>','06')
# YouTube : post de communauté / miniature 16:9
job('manifeste/youtube-16x9',160,90,8,photo(CO,'center 45%',.6)+spot('30%','50%',.3)+f'<div style="position:absolute;left:8px;top:7px">{logo(10)}</div><div class="H" style="position:absolute;left:8px;top:30px;font-size:9px">La nouvelle ère du foot à 5</div><div class="H C" style="position:absolute;left:8px;top:39px;font-size:24px">Mercenaires</div><div class="H C" style="position:absolute;left:8px;top:68px;font-size:13px">du dimanche.</div>'+edge())
json.dump(JOBS,open('jobs8.json','w')); print(len(JOBS))
